        texte: f.texte,
        sources: f.sources,
        alertes: f.alertes,
        avertissements: f.avertissements,
        retirees: [],
        analyse: tache ? { statut: 'en_cours', tache_id: tache } : { statut: 'desactivee' },
      },
      evenement_journal: {
        evenement: 'verification',
        patient_id: c.patient.patient_id,
        mode: 'a',
        action: 'verifier_document',
        prompt_id: 'verifier_document',
        prompt_version: f.prompt_versions,
        details: { brouillon_id: b.id, lettre: f.lettre_ref, contradictions_regles: f.nb_regles, analyse_ia: tache ? 'en_cours' : 'desactivee', tache_id: tache },
      },
    },
  },
];

// Contrôle de session – le jeton « Bearer » de l'en-tête Authorization (43 caractères URL-safe) est haché (SHA-256) : seul le haché est en base.
const entetes = $input.first().json?.headers ?? {};
const m = String(entetes.authorization ?? '').match(/^Bearer ([A-Za-z0-9_-]{43})$/);
if (!m) return [{ json: { hash: '' } }];
return [{ json: { hash: require('crypto').createHash('sha256').update(m[1]).digest('hex') } }];

// Contrôle de session – résultat : un soignant identifié (session ouverte, non expirée, compte actif) ou rien.
const r = $input.first().json ?? {};
if (!r.identifiant) return [{ json: { ok: false } }];
return [{ json: { ok: true, soignant: { identifiant: r.identifiant, nom: r.nom }, jeton_hash: r.jeton_hash } }];
